-- The AP pack (Plan entry §1.233, Wave Y item Y4; ARCHITECTURE §10.24): `ap_bill` (one bill to
-- pay per purchase: its match to a purchase order, its flags, the week's approve-to-pay list it is
-- on and a person's decision), `ap_bill_line` (each line's account, and a model's suggestion kept
-- apart until a person takes it) and `ap_receipt` (goods received against an order, a log). No
-- payment: nothing here pays or schedules one. New tables only, so the previous Worker keeps
-- working. Generated by drizzle-kit from packs/materials/src/ap/schema.ts; the grants, row-level
-- security, history trigger and pack comments at the end are hand-written.
CREATE TABLE "ap_bill" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"transaction_id" uuid NOT NULL,
	"document_id" uuid,
	"extraction_id" uuid,
	"vendor_id" uuid,
	"invoice_number" text,
	"invoice_date" date,
	"due_date" date,
	"amount" numeric(14, 4) NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"match_status" text DEFAULT 'pending' NOT NULL,
	"purchase_request_id" uuid,
	"match" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"flags" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"pay_week" date,
	"decided_by" uuid,
	"decided_at" timestamp with time zone,
	"decision_note" text,
	"agent_version_id" uuid,
	"run_id" uuid,
	"sources" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ap_bill_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "ap_bill_transaction_key" UNIQUE("tenant_id","transaction_id"),
	CONSTRAINT "ap_bill_status_check" CHECK ("ap_bill"."status" in ('open', 'approved', 'held', 'rejected')),
	CONSTRAINT "ap_bill_match_status_check" CHECK ("ap_bill"."match_status" in ('pending', 'matched', 'partial', 'proposed', 'none')),
	CONSTRAINT "ap_bill_currency_check" CHECK ("ap_bill"."currency" ~ '^[A-Z]{3}$'),
	CONSTRAINT "ap_bill_decided_check" CHECK (("ap_bill"."status" = 'open') = ("ap_bill"."decided_by" is null) and ("ap_bill"."decided_by" is null) = ("ap_bill"."decided_at" is null)),
	CONSTRAINT "ap_bill_listed_check" CHECK ("ap_bill"."status" = 'open' or "ap_bill"."pay_week" is not null),
	CONSTRAINT "ap_bill_pay_week_check" CHECK ("ap_bill"."pay_week" is null or extract(isodow from "ap_bill"."pay_week") = 1),
	CONSTRAINT "ap_bill_order_check" CHECK (("ap_bill"."purchase_request_id" is not null) = ("ap_bill"."match_status" in ('matched', 'partial', 'proposed'))),
	CONSTRAINT "ap_bill_flags_check" CHECK (jsonb_typeof("ap_bill"."flags") = 'array'),
	CONSTRAINT "ap_bill_sources_check" CHECK (jsonb_typeof("ap_bill"."sources") = 'array'),
	CONSTRAINT "ap_bill_note_check" CHECK ("ap_bill"."decision_note" is null or length("ap_bill"."decision_note") <= 1000)
);
--> statement-breakpoint
CREATE TABLE "ap_bill_line" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"ap_bill_id" uuid NOT NULL,
	"line_no" integer NOT NULL,
	"doc_line_id" uuid,
	"amount" numeric(14, 4) NOT NULL,
	"ledger_account_id" uuid,
	"coded_by" text,
	"coded_by_user_id" uuid,
	"proposed_ledger_account_id" uuid,
	"proposal_reason" text,
	"proposal_agent_version_id" uuid,
	"purchase_request_line_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ap_bill_line_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "ap_bill_line_no_key" UNIQUE("ap_bill_id","line_no"),
	CONSTRAINT "ap_bill_line_no_check" CHECK ("ap_bill_line"."line_no" >= 1),
	CONSTRAINT "ap_bill_line_coded_by_check" CHECK ("ap_bill_line"."coded_by" is null or "ap_bill_line"."coded_by" in ('history', 'person')),
	CONSTRAINT "ap_bill_line_coded_check" CHECK (("ap_bill_line"."ledger_account_id" is null) = ("ap_bill_line"."coded_by" is null) and ("ap_bill_line"."coded_by_user_id" is not null) = (coalesce("ap_bill_line"."coded_by", '') = 'person')),
	CONSTRAINT "ap_bill_line_proposal_check" CHECK (("ap_bill_line"."proposed_ledger_account_id" is null) = ("ap_bill_line"."proposal_agent_version_id" is null) and ("ap_bill_line"."proposal_reason" is null or length("ap_bill_line"."proposal_reason") <= 500))
);
--> statement-breakpoint
CREATE TABLE "ap_receipt" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"purchase_request_id" uuid NOT NULL,
	"purchase_request_line_id" uuid,
	"qty" numeric(14, 4),
	"received_on" date NOT NULL,
	"document_id" uuid,
	"note" text,
	"recorded_by_user_id" uuid,
	"agent_version_id" uuid,
	"run_id" uuid,
	"sources" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ap_receipt_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "ap_receipt_qty_check" CHECK (("ap_receipt"."purchase_request_line_id" is null) = ("ap_receipt"."qty" is null) and ("ap_receipt"."qty" is null or "ap_receipt"."qty" <> 0)),
	CONSTRAINT "ap_receipt_recorded_by_check" CHECK (num_nonnulls("ap_receipt"."recorded_by_user_id", "ap_receipt"."agent_version_id") = 1),
	CONSTRAINT "ap_receipt_note_check" CHECK ("ap_receipt"."note" is null or length("ap_receipt"."note") <= 500),
	CONSTRAINT "ap_receipt_sources_check" CHECK (jsonb_typeof("ap_receipt"."sources") = 'array')
);
