-- A bill and its lines are prepared again and decided (updates), never deleted.
GRANT SELECT, INSERT, UPDATE ON ap_bill, ap_bill_line TO cs_runtime;
--> statement-breakpoint
-- Receipts are a log: a correction is a new row.
GRANT SELECT, INSERT ON ap_receipt TO cs_runtime;
--> statement-breakpoint
CREATE TRIGGER ap_receipt_immutable BEFORE UPDATE OR DELETE ON ap_receipt
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ap_bill', 'ap_bill_line', 'ap_receipt'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
    EXECUTE format('COMMENT ON TABLE %I IS %L', t, 'pack:ap');
  END LOOP;
END
$$;
